        f.vx *= 0.5; f.vy *= 0.5;
        if (finEdge(f, o, a, true) > K.ctKeep) { a.bodyPen = Math.max(a.bodyPen || 0, 0.12); float('硬扣', f, '#ffd24a', 1); }   // 对抗占优：扛着人继续扣
        else if (d2l(f, a, 0.3)) float('改上篮', f, '#f6efe0', 1);
