    let tier = kind === 'dunk' ? (special ? 2 : 1) : pts === 3 ? 1 : 0, ledT = kind === 'dunk' ? 'SLAM DUNK  ' + (name || '暴扣') + '  +2' : pts === 3 ? '3 POINTS  三分  +3' : '+2  ' + (name || '两分');
