    post: { n: '内线', en: 'POST', keys: ['post', 'hook', 'str', 'close', 'sdunk'], ab: ['每次顶人都能顶开', '背打出手被干扰 -50%'] },
    hnd: { n: '运球', en: 'HANDLES', keys: ['hnd', 'acc', 'spd'], ab: ['晃人成功率 ×1.6', '运球动作体力 -60%'] },
    def: { n: '防守', en: 'LOCKDOWN', keys: ['def', 'intD', 'stl', 'blk', 'dreb'], ab: ['盖帽抢断成功率 ×1.4', '干扰 +30%'] }
