      if (b.trail) part(b.x, b.y, b.z, rr(-0.2, 0.2), rr(-0.2, 0.2), rr(-0.2, 0.4), b.trail, 0.28, 0);
      if (s.win && !s.slowed && s.T - s.t < K.fxWinSlowT) { s.slowed = true; G.fx.slow = K.fxWinSlow; }
